const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = (v='') => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderText(value=''){const text=String(value),pattern=/\[([^\]\n]{1,300})\]\((https?:\/\/[^\s)]+)\)|(https?:\/\/[^\s<>]+)/g;let out='',last=0;for(const match of text.matchAll(pattern)){out+=esc(text.slice(last,match.index));const markdown=Boolean(match[2]);let href=match[2]||match[3],tail='';if(!markdown){const trimmed=href.replace(/[.,;!?)]+$/,'');tail=href.slice(trimmed.length);href=trimmed;}try{const url=new URL(href);if(!['http:','https:'].includes(url.protocol))throw Error('protocol');out+=`<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(markdown?match[1]:href)}</a>`+esc(tail);}catch{out+=esc(match[0]);}last=match.index+match[0].length;}return out+esc(text.slice(last));}
const icons={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',film:'M4 3h16v18H4zM4 8h16M4 16h16M8 3v18M16 3v18',company:'M4 21V5h11v16M15 11h5v10M8 9h3M8 13h3M8 17h3M2 21h20',chat:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8A8.5 8.5 0 0 1 8.7 4a8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z',memory:'M9 18h6M9 21h6M8.1 14.5A6 6 0 1 1 16 14.4c-1 1-1 2.6-1 3.6H9c0-1 0-2.5-.9-3.5',search:'M21 21l-5.5-5.5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M3 12h2M19 12h2M12 3v2M12 19v2M5.6 5.6 7 7M17 17l1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',close:'m6 6 12 12M6 18 18 6',upload:'M12 16V3M7 8l5-5 5 5M3 15v6h18v-6',folder:'M3 6h7l2 3h9v12H3z',file:'M6 2h8l5 5v15H6zM14 2v6h5M9 12h7M9 16h7',check:'m5 12 4 4L19 6',more:'M4 12h.01M12 12h.01M20 12h.01',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',edit:'m4 15 12-12 5 5L9 20l-6 1zM13 6l5 5',down:'m6 9 6 6 6-6',up:'m6 15 6-6 6 6',play:'m8 4 13 8-13 8z',download:'M12 3v13M7 11l5 5 5-5M3 16v5h18v-5',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',pause:'M8 4v16M16 4v16',refresh:'M21 3v6h-6M3 21v-6h6M5 7a8 8 0 0 1 13-2l3 4M3 15l3 4a8 8 0 0 0 13-2',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',palette:'M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-4 2 2 0 0 1 1-4h3a3 3 0 0 0 3-3c0-4-4-7-9-7M7 9h.01M10 6h.01M15 6h.01M18 9h.01',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7M9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0',copy:'M9 9h12v12H9zM15 9V3H3v12h6'};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const badge = (text, kind='') => `<span class="badge ${kind}">${esc(text)}</span>`;
const assetURL = a => `/api/assets/${encodeURIComponent(typeof a==='string'?a:a.id)}/content`;
const hex = (v) => /^#[0-9a-f]{6}$/i.test(v||'') ? v.toUpperCase() : null;
const rgb = h => [1,3,5].map(i=>parseInt((hex(h)||'#000000').slice(i,i+2),16));
const percent = v => Math.max(0,Math.min(100,v<=1?v*100:v));
const formatDate = v => v ? new Date(v).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}) : '';
const sizes = v => v ? `${(v/1073741824).toFixed(1)} GB` : 'A verificar';
const state = {data:{companies:[],projects:[],settings:{}},view:'home',company:localStorage.getItem('studio_company')||'',project:null,setupStep:0,setupStatus:null,diagnostics:null,chatBusy:false,messages:[],memory:[],results:null,companyDraft:null,companyTab:'identity',paletteSuggestions:[],projectDraft:null,modal:null,setupFolder:'',poll:null};
async function api(path, opts={}) { const headers={...opts.headers}; if(opts.body&&!(opts.body instanceof FormData)){headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body);} const r=await fetch('/api'+path,{...opts,headers,credentials:'same-origin'});const ct=r.headers.get('content-type')||'';const payload=ct.includes('json')?await r.json():await r.text();if(!r.ok)throw Error(payload.error||payload.message||payload||`Erro ${r.status}`);return payload; }
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),error?10000:5000);}
function btn(label,action,ic,cls='',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${label}</button>`;}
function company(){return (state.data.companies||[]).find(c=>c.id===state.company);}
function activeProject(){return state.project;}
function sourceName(p){return p.source_name||state.data.companies.find(c=>c.id===p.company_id)?.assets?.find(a=>a.id===p.source_asset_id)?.name||String(p.source||'').split(/[\\/]/).pop();}
async function refresh(){state.data=await api('/state');state.data.companies ||= [];state.data.projects ||= [];state.data.settings ||= {};if(state.company&&!company()){state.company='';localStorage.removeItem('studio_company');}if(!state.company&&state.data.companies.length===1){state.company=state.data.companies[0].id;localStorage.setItem('studio_company',state.company);}return state.data;}
function titleForView(){return ({home:'Início',companies:'Empresas',projects:'Projetos',chat:'Assistente',memory:'Memória',documents:'Documentos',settings:'Configurações'})[state.view]||'Estúdio';}
function render(){if(!state.data.installed){renderSetup();return;}const c=company();$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-symbol">e</span><div class="brand-copy"><b>Estúdio Local</b><small>Seu assistente de vídeo</small></div></div><nav class="nav" aria-label="Navegação principal">${[['home','home','Início'],['projects','film','Meus projetos'],['chat','chat','Assistente'],['companies','company','Empresas'],['documents','file','Documentos'],['memory','memory','Memória']].map(([v,i,n])=>`<button data-action="nav" data-view="${v}" class="${state.view===v?'active':''}" title="${n}">${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><button data-action="nav" data-view="settings" class="${state.view==='settings'?'active':''}" title="Configurações">${icon('settings')}<span>Configurações</span></button></nav><div class="local-note"><strong>● Tudo no seu computador</strong>Os arquivos importados e as conversas ficam neste PC.</div></div></aside><div class="content"><header class="topbar"><div class="topbar-path">Seu espaço <span>/</span> <b>${titleForView()}</b></div><div class="row"><select id="company-switch" aria-label="Empresa ativa"><option value="">Selecionar empresa</option>${state.data.companies.map(c=>`<option value="${esc(c.id)}" ${state.company===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="badge green"><span class="dot"></span> Local</span></div></header><main class="page" id="page">${viewHTML()}</main></div></div>`;if(state.view==='chat')scrollChat();}
function viewHTML(){switch(state.view){case 'companies':return companiesHTML();case 'projects':return projectsHTML();case 'chat':return chatHTML();case 'memory':return memoryHTML();case 'documents':return documentsHTML();case 'settings':return settingsHTML();default:return homeHTML();}}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
function companyCards(includeAdd=true){return `<div class="companies-grid">${state.data.companies.map(c=>`<button class="company-card" data-action="select-company" data-id="${esc(c.id)}"><div class="company-avatar">${c.logo_uri?`<img src="${esc(c.logo_uri)}" alt="">`:logoAsset(c)?`<img src="${assetURL(logoAsset(c))}" alt="">`:esc(c.name?.slice(0,2).toUpperCase()||'EM')}</div><div class="swatches">${(c.colors||[]).slice(0,5).map(x=>`<span class="swatch" style="background:${hex(x.hex)||'#ddd'}"></span>`).join('')}</div><h3>${esc(c.name)}</h3><p>${(c.assets||[]).length} materiais · ${c.colors?.length||0} cores${state.company===c.id?' · selecionada':''}</p></button>`).join('')}${includeAdd?`<button class="company-card add-company" data-action="new-company">${icon('plus')}<span>Adicionar empresa</span></button>`:''}</div>`;}
function logoAsset(c){return (c?.assets||[]).find(a=>a.kind==='logo');}
function projectRows(projects){return projects.length?`<div class="project-list">${projects.map(p=>`<button class="project-row" data-action="open-project" data-id="${esc(p.id)}"><span class="project-icon">${icon('film')}</span><span class="grow"><h3>${esc(p.title||'Vídeo sem título')}</h3><p>${esc(state.data.companies.find(c=>c.id===p.company_id)?.name||'Empresa')} · ${esc(p.aspect||'Formato a definir')} · ${esc(typeof p.duration==='object'?p.duration.mode:p.duration||'Duração a definir')}</p></span><span class="date">${formatDate(p.updated_at||p.updated||p.created_at||p.created)}</span>${icon('arrow')}</button>`).join('')}</div>`:`<div class="empty">${icon('film')}<h3>Seu próximo vídeo começa aqui</h3><p>Escolha uma empresa e conte o que quer criar. Os detalhes pertencem a cada projeto.</p>${btn('Criar primeiro vídeo','new-project','plus','small')}</div>`;}
function homeHTML(){return `${heading('O que vamos criar hoje?','Escolha uma empresa, traga sua ideia e deixe o agente ajudar.',btn('Novo vídeo','new-project','plus','primary'))}<section class="hero"><div><span class="uppercase" style="color:#8979a4">DA IDEIA AO ARQUIVO FINAL</span><h2 style="margin-top:13px">Um espaço para seus vídeos.<br>Cada marca, do seu jeito.</h2><p>Edite, legende e crie animações usando os materiais da empresa e as escolhas de cada projeto.</p>${btn('Começar um vídeo','new-project','arrow','dark')}</div><div class="hero-art" aria-hidden="true"><div class="mini-frame"><span></span><span></span></div><div class="mini-frame"><i>Aa</i><span></span><span></span></div><div class="mini-frame"><span></span><span></span></div></div></section><div class="section-title"><h2>Suas empresas</h2>${btn('Gerenciar','nav',null,'ghost small','data-view="companies"')}</div>${companyCards()}<div class="section-title"><h2>Projetos recentes${company()?' · '+esc(company().name):''}</h2>${btn('Ver todos','nav',null,'ghost small','data-view="projects"')}</div><section class="card">${projectRows(state.data.projects.filter(p=>!state.company||p.company_id===state.company).slice(0,5))}</section>`;}
function companiesHTML(){const c=company();return `${heading('Empresas','Identidade e orientações permanentes. As escolhas de vídeo ficam em cada projeto.',btn('Adicionar empresa','new-company','plus','primary'))}${companyCards(false)}${c?`<div class="section-title"><h2>${esc(c.name)}</h2><div class="row">${btn('Exportar cadastro','export-company','download','small')}${btn('Editar identidade','edit-company','edit','small primary','data-id="'+esc(c.id)+'"')}</div></div><section class="card"><div class="grid2"><div><h3>Identidade visual</h3><p class="muted small">${esc(c.description||'Adicione uma descrição para facilitar a identificação da marca.')}</p><div class="row wrap">${(c.colors||[]).map(x=>`<span class="badge"><span class="swatch" style="background:${hex(x.hex)||'#ddd'}"></span>${esc(x.name||x.role||x.hex)}</span>`).join('')||'<span class="muted small">Paleta neutra provisória · identidade ainda não cadastrada.</span>'}</div></div><div><h3>Instruções permanentes</h3><p class="muted small" style="white-space:pre-wrap">${esc(c.instructions||'Nenhuma instrução permanente cadastrada.')}</p></div></div><div class="divider"></div><h3>Materiais da empresa</h3>${assetList(c.assets||[])}<div class="row wrap" style="margin-top:20px">${btn('Importar cadastro de outra instalação','import-company','upload','small')}${btn('Excluir empresa','delete-company','trash','small danger')}</div></section>`:`<div class="notice" style="margin-top:25px">Selecione uma empresa para editar suas fontes, logos, cores e documentos.</div><div style="margin-top:15px">${btn('Importar cadastro','import-company','upload','small')}</div>`}`;}
function projectsHTML(){return `${heading('Meus projetos','Briefing, formato, duração e áudio definidos para cada vídeo.',btn('Novo vídeo','new-project','plus','primary'))}<section class="card">${projectRows(state.data.projects.filter(p=>!state.company||p.company_id===state.company))}</section>`;}
function chatHTML(){const p=activeProject(), c=company();return `${heading(p?esc(p.title||'Projeto de vídeo'):'Seu assistente',c?'Trabalhando com '+esc(c.name):'Selecione uma empresa para começar.',p?btn('Detalhes do projeto','project-details','settings','small'):btn('Novo vídeo','new-project','plus','primary'))}<div class="workspace"><section class="chat-box"><div class="chat-title row between"><div><h3>${c?esc(c.name):'Selecione uma empresa'}</h3><span class="muted tiny">${p?'Projeto individual · arquivos e decisões organizados aqui':'Conversa local · sem configurações de vídeo herdadas'}</span></div>${badge('Assistente','purple')}</div><div class="messages" id="messages">${messagesHTML()}</div><form id="chat-form" class="chat-compose"><div class="compose-input"><textarea id="chat-input" placeholder="Conte o que você quer fazer…" aria-label="Mensagem ao assistente" ${!c?'disabled':''}></textarea><div class="row between"><div class="row">${p?btn('Adicionar arquivo','project-upload','plus','ghost small'):''}<span class="tiny muted">${state.chatBusy?'Trabalhando…':'Enter envia · Shift + Enter quebra linha'}</span></div>${state.chatBusy?btn('Parar resposta','stop-chat','pause','small'):''}<button class="btn primary small" id="send-button" type="submit" ${!c||state.chatBusy?'disabled':''}>${icon('arrow')}<span>Enviar</span></button></div></div></form></section><aside class="side-stack">${p?projectSideHTML(p):`<section class="card"><h3>Como posso ajudar?</h3><p class="small muted">Você pode pedir uma edição, escrever um prompt, explorar ideias ou consultar documentos importados.</p><div class="stack">${btn('Criar um vídeo','new-project','film','small')}${btn('Consultar documentos','nav','file','small','data-view="documents"')}${btn('Ver memória da empresa','nav','memory','small','data-view="memory"')}</div></section>`}<section class="card"><h3>Você no controle</h3><p class="small muted" style="margin:0">O agente trabalha com o acesso escolhido e mantém os arquivos originais. Web search precisa de internet; documentos locais permanecem no PC.</p></section></aside></div>`;}
function messagesHTML(){return state.messages.length?state.messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}">${m.role!=='user'?'<span class="speaker">Estúdio Local</span>':''}${renderText(m.content||m.text||'')}</div>`).join(''):`<div class="chat-welcome"><span class="brand-symbol">e</span><h2>${state.project?'Vamos trabalhar neste vídeo':'Pode começar com uma ideia'}</h2><p>${state.project?'Os detalhes que você escolheu já estão no projeto. Peça uma ação ou deixe o agente sugerir o próximo passo.':'Converse normalmente ou crie um projeto para organizar a produção.'}</p><div class="quick-actions">${['Me ajude a desenvolver uma ideia','Crie um prompt de vídeo em inglês'].map(t=>`<button class="chip" data-action="suggest" data-text="${esc(t)}">${esc(t)}</button>`).join('')}</div></div>`;}
const actions=[['transcribe','Transcrever','file'],['plan_silence','Remover pausas','pause'],['captions','Legendar','chat'],['frames','Ver fotogramas','eye'],['motion','Criar motion','play'],['edit','Exportar edição','film']];
function projectSideHTML(p){const audio=typeof p.audio==='object'?p.audio.mode:p.audio;return `<section class="card project-info"><h3>Este vídeo</h3>${p.source?`<p class="small muted" style="overflow-wrap:anywhere">${esc(sourceName(p))}</p><details><summary class="small muted" style="cursor:pointer;margin-bottom:10px">Ver arquivo original</summary><video class="media-preview" controls preload="metadata" src="/api/file?project_id=${encodeURIComponent(p.id)}&path=${encodeURIComponent(p.source)}"></video></details>`:''}${[['Formato',p.aspect||'A definir'],['Duração',typeof p.duration==='object'?p.duration.mode:p.duration||'A definir'],['Áudio',({original:'Original',none:'Sem áudio',music:'Trilha',narration:'Narração',mix:'Combinação'})[audio]||'A definir'],['Acesso',({files:'Arquivos selecionados',company:'Pastas da empresa',folder:'Pasta escolhida',computer:'Arquivos do usuário'})[p.scope]||'Arquivos selecionados']].map(([k,v])=>`<div class="info-row"><span class="label">${k}</span><span>${esc(v)}</span></div>`).join('')}<div class="divider" style="margin:15px 0"></div><h3>Ações do projeto</h3><div class="quick-actions">${actions.map(([a,t])=>`<button class="chip" data-action="run-job" data-job="${a}">${t}</button>`).join('')}</div></section><section class="card"><div class="row between"><h3 style="margin:0">Etapas e arquivos</h3><button class="icon-btn" data-action="refresh-jobs" title="Atualizar etapas">${icon('refresh')}</button></div><div id="jobs-area"><p class="muted small" style="margin:15px 0 0">Carregando etapas…</p></div>${p.output_dir?btn('Abrir pasta de saída','open-path','folder','small','data-path="'+esc(p.output_dir)+'" style="margin-top:15px"'):''}</section>`;}
function memoryHTML(){const enabled=state.data.settings.memory_enabled!==false;return `${heading('Memória','Preferências e decisões úteis, com origem e escopo visíveis.',btn('Adicionar memória','new-memory','plus','primary'))}<div class="notice">${company()?`Empresa selecionada: <strong>${esc(company().name)}</strong>. `:'Selecione uma empresa para consultar suas memórias. '}Duração, formato, áudio e briefing de um vídeo permanecem no próprio projeto.</div><div class="row between wrap" style="margin:20px 0"><label class="row small"><input type="checkbox" id="memory-toggle" ${enabled?'checked':''}> Guardar preferências úteis automaticamente</label><div class="row">${btn('Exportar','export-memories','download','small')}${btn('Backup','backup','copy','small')}</div></div><div id="memory-list">${state.memory.length?state.memory.map(m=>`<article class="memory-card"><div class="row between">${badge(m.scope==='project'?'Projeto':m.scope==='personal'?'Pessoal':'Empresa')}<div class="row"><button class="icon-btn" data-action="edit-memory" data-id="${esc(m.id)}" title="Editar memória">${icon('edit')}</button><button class="icon-btn" data-action="delete-memory" data-id="${esc(m.id)}" title="Esquecer memória">${icon('trash')}</button></div></div><p>${esc(m.content||m.text)}</p><div class="meta">${esc(m.source||m.provenance||'Informada pelo usuário')} · ${formatDate(m.updated_at||m.updated||m.created_at||m.created)}</div></article>`).join(''):`<div class="empty">${icon('memory')}<h3>Nenhuma memória aqui ainda</h3><p>As preferências salvas aparecerão nesta tela para você revisar, editar ou esquecer.</p></div>`}</div><p class="tiny muted">Ao esquecer, a entrada deixa de ser usada em novas respostas. Backups anteriores podem conservar a versão antiga até serem removidos.</p>`;}
function documentsHTML(){const c=company();return `${heading('Documentos da empresa','Consulte apenas os materiais importados para a empresa selecionada.',c?btn('Importar documentos','edit-company','upload','primary',`data-id="${esc(c.id)}" data-tab="documents"`):'')}<form id="search-form" class="search-form"><input name="q" aria-label="Buscar nos documentos" placeholder="Buscar nos manuais, referências e briefings antigos…" ${!c?'disabled':''}><button class="btn primary" ${!c?'disabled':''}>${icon('search')}Buscar</button></form><section class="card">${state.results?`<h3>Resultados da consulta</h3>${state.results.length?state.results.map(r=>`<article class="search-result"><h3>${esc(r.title||r.name||r.source||'Documento')}</h3><p>${esc(r.snippet||r.text||r.content||'')}</p><span class="tiny muted">${esc(r.kind||'Referência')} ${r.page?'· página '+esc(r.page):''} ${r.section?'· '+esc(r.section):''}</span>${r.asset_id?` <a href="${assetURL(r.asset_id)}" target="_blank" rel="noopener">Abrir fonte</a>`:''}</article>`).join(''):'<p class="muted small">Nenhum trecho encontrado. Tente outro termo ou importe documentos com texto extraível.</p>'}`:`<h3>Materiais cadastrados</h3>${assetList((c?.assets||[]).filter(a=>!['logo','font'].includes(a.kind)))}`}</section><div class="notice" style="margin-top:18px">Briefings antigos são referências históricas. Preços, ofertas e decisões anteriores precisam ser confirmados para o vídeo atual.</div>`;}
function settingsHTML(){return `${heading('Configurações','Um único aplicativo. Os serviços técnicos são gerenciados nos bastidores.')}<div class="grid2"><section class="card"><h3>Funcionamento local</h3><p class="small muted">Verifique componentes, GPU, armazenamento e mensagens de erro sem abrir outro aplicativo.</p><div class="stack">${btn('Diagnóstico do computador','diagnostics','bolt')}${btn('Criar backup dos dados','backup','copy')}${btn('Reparar componentes','repair','refresh')}${btn('Encerrar aplicativo','shutdown','close','ghost')}</div></section><section class="card"><h3>Seus dados</h3><p class="small muted">Empresas, projetos, fontes e documentos são armazenados localmente.</p><p class="small" style="overflow-wrap:anywhere">${esc(state.data.data_dir||state.data.settings.data_dir||'Pasta gerenciada pelo aplicativo')}</p>${btn('Abrir pasta dos dados','open-data','folder','small')}<div class="divider"></div><label class="row small"><input type="checkbox" id="memory-toggle" ${state.data.settings.memory_enabled!==false?'checked':''}> Memória automática</label></section></div><section class="card" style="margin-top:20px"><h3>Acesso aos arquivos</h3><p class="muted small">O acesso é escolhido em cada projeto: arquivos selecionados, pasta específica, pastas aprovadas da empresa ou arquivos acessíveis ao usuário atual do Windows. A seleção de empresa organiza o trabalho; ela não substitui contas e permissões corporativas.</p><p class="muted small" style="margin:0">O aplicativo não solicita acesso de administrador para contornar permissões. Em caso de bloqueio pela rede ou pelo Windows, compartilhe o diagnóstico com o TI.</p></section>`;}
const kindLabels={logo:'Logo',font:'Fonte',reference:'Referência',manual:'Manual da marca',briefing:'Briefing antigo',instructions:'Instruções permanentes',file:'Arquivo',video:'Vídeo',audio:'Áudio',image:'Imagem'};
function assetList(assets){return assets.length?`<div class="upload-list">${assets.map(a=>`<div class="asset-row">${a.kind==='logo'?`<img src="${assetURL(a)}" alt="Logo importado">`:icon(a.kind==='font'?'palette':'file')}<div class="grow"><div>${esc(a.name||a.filename||'Arquivo')}</div><small class="muted">${esc(kindLabels[a.kind]||a.kind||'Arquivo')}${a.status||a.extraction_status?' · '+esc(({ready:'Pronto',indexing:'Indexando',failed:'Falhou',pending:'Na fila'})[a.status||a.extraction_status]||a.status||a.extraction_status):''}</small></div><a class="icon-btn" href="${assetURL(a)}" target="_blank" rel="noopener" title="Abrir arquivo">${icon('eye')}</a></div>`).join('')}</div>`:'<p class="small muted">Nenhum material importado. Você pode adicionar depois.</p>';}
function renderSetup(){const step=state.setupStep;$('#app').innerHTML=`<div class="setup-shell"><div class="setup-top"><div class="brand"><span class="brand-symbol">e</span><div class="brand-copy"><b>Estúdio Local</b><small>Preparar seu assistente de vídeo</small></div></div>${badge('Instalação neste computador','green')}</div><div class="setup-progress">${['Seu computador','Suas empresas','Componentes','Instalação'].map((n,i)=>`${i?'<span class="setup-line"></span>':''}<div class="setup-step ${step===i?'current':step>i?'done':''}"><b>${step>i?'✓':i+1}</b><span>${n}</span></div>`).join('')}</div><main class="setup-main">${setupHTML(step)}</main></div>`;}
function setupHTML(step){const d=state.diagnostics||{};if(step===0)return `<div class="setup-intro"><h1>Seu estúdio, neste computador.</h1><p>Primeiro vamos preparar o espaço. Depois você cadastra as empresas e instala os componentes.</p></div><div class="hardware-grid"><div class="hardware-item"><span class="label">Sistema</span><strong>${esc(d.os||d.platform||'Indisponível')}</strong></div><div class="hardware-item"><span class="label">Placa de vídeo</span><strong>${esc(d.gpu?.name||d.gpu_name||(typeof d.gpu==='string'?d.gpu:'A verificar na instalação'))}</strong></div><div class="hardware-item"><span class="label">Espaço disponível</span><strong>${d.free_gb?esc(d.free_gb)+' GB':sizes(d.free_bytes||d.disk_free_bytes)}</strong></div></div><section class="card"><h3>Onde guardar os materiais?</h3><p class="muted small">As empresas, conversas e projetos ficarão nesta pasta. Os arquivos originais que você importar serão preservados.</p><div class="row"><div class="field grow"><input id="setup-folder" value="${esc(state.setupFolder||state.data.data_dir||'')}" placeholder="Pasta padrão do aplicativo" readonly aria-label="Pasta dos dados"></div>${btn('Escolher pasta','pick-data','folder')}</div><div class="notice" style="margin-top:18px">Os modelos e componentes de vídeo exigem vários gigabytes. O instalador verificará espaço e compatibilidade antes de baixar. A conexão é necessária nesta etapa.</div></section><div class="setup-footer">${btn('Ver diagnóstico','diagnostics','bolt','ghost')} ${btn('Continuar','setup-next','arrow','primary')}</div>`;if(step===1)return `<div class="setup-intro"><h1>Uma identidade para cada empresa.</h1><p>Cadastre logos, cores, fontes e orientações permanentes. Também pode fazer isso mais tarde.</p></div>${companyCards()}<div class="notice" style="margin-top:23px">Aqui entram somente os dados permanentes da marca. <strong>Briefing, duração, formato e áudio serão escolhidos ao criar cada vídeo.</strong></div><div class="setup-footer">${btn('Voltar','setup-back',null,'ghost')}<div class="row">${btn('Configurar depois','setup-next',null,'ghost')}${btn('Continuar','setup-next','arrow','primary')}</div></div>`;if(step===2)return `<div class="setup-intro"><h1>Pronto para preparar as ferramentas.</h1><p>Você vai usar uma única interface. O aplicativo cuida dos componentes por trás.</p></div>${[['chat','Assistente e memória local','Conversa em português, modelos locais, documentos e memória por empresa.'],['film','Edição, legendas e áudio','FFmpeg, transcrição multilíngue e ferramentas de exportação.'],['play','Animações com Remotion','Composições locais, fontes e navegador de renderização.']].map(([i,h,p])=>`<div class="module-card">${icon(i)}<div class="grow"><h3>${h}</h3><p>${p}</p></div>${badge('Essencial')}</div>`).join('')}<div class="notice warning" style="margin:20px 0">O uso do Remotion por uma rede de empresas pode exigir licença própria. Confira as <a href="https://www.remotion.dev/docs/license/pricing" target="_blank" rel="noopener">condições oficiais de uso</a> antes de instalar. Nenhuma licença será comprada automaticamente.</div><label class="row small" style="align-items:start"><input id="license-ack" type="checkbox"><span>Li as condições de uso do Remotion e confirmo que a organização atende às condições de uso ou possui a licença necessária.</span></label><p class="tiny muted" style="margin-top:17px">Downloads e tamanhos serão exibidos pelo instalador. Você poderá acompanhar as etapas, interromper e retomar.</p><div class="setup-footer">${btn('Voltar','setup-back',null,'ghost')}${btn('Instalar componentes','start-install','download','primary')}</div>`;return `<div class="setup-intro"><h1>Preparando seu estúdio.</h1><p>Acompanhe os downloads e as verificações. Seus cadastros já foram salvos.</p></div><section class="card" id="setup-progress-card">${setupStatusHTML()}</section><div class="setup-footer">${btn('Atualizar estado','refresh-setup','refresh','ghost')}<div class="row">${btn('Tentar novamente','retry-setup','refresh','small')}${btn('Interromper','cancel-setup','pause','small')}</div></div>`;}
function setupStatusHTML(){const s=state.setupStatus||{};const lines=s.events||s.logs||s.log||[];return `<div class="row between"><h3 style="margin:0">${esc(s.message||s.stage||s.status||'Aguardando o instalador…')}</h3>${['failed','error'].includes(s.status)?badge('Precisa de atenção'):['completed','ready','done'].includes(s.status)?badge('Pronto','green'):'<span class="spinner"></span>'}</div>${Number.isFinite(s.progress)?`<div class="progress-track" style="margin:20px 0"><div class="progress-bar" style="width:${percent(s.progress)}%"></div></div>`:'<p class="small muted" style="margin-top:16px">A etapa informa progresso quando o componente disponibiliza essa informação.</p>'}${s.error?`<div class="notice error" style="margin:15px 0">${esc(s.error)}</div>`:''}${lines.length?`<div class="setup-log">${esc(Array.isArray(lines)?lines.slice(-30).map(l=>typeof l==='string'?l:l.message||JSON.stringify(l)).join('\n'):lines)}</div>`:''}${['completed','ready','done'].includes(s.status)?btn('Abrir o estúdio','finish-setup','arrow','primary','style="margin-top:20px"'):''}`;}
function showModal(title,body,foot='',wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" title="Fechar">${icon('close')}</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`;$('#modal-root .modal-head button')?.focus();}
function closeModal(){if(state.chatBusy&&state.modal==='project')return;if(state.playerCleanup){state.playerCleanup();state.playerCleanup=null;}$('#modal-root').innerHTML='';state.modal=null;}
function normalizeCompany(c){const d=structuredClone(c||newDraft());d.assets ||= [];d.colors ||= [];d.folders ||= [];d.font_roles ||= {};return d;}
function newDraft(){return {name:'',description:'',instructions:'',colors:[],assets:[],folders:[],font_roles:{},shared:false};}
async function openCompany(id,tab='identity'){const c=state.data.companies.find(x=>x.id===id);state.companyDraft=normalizeCompany(c);if(!id){try{const cached=localStorage.getItem('studio_company_draft');if(cached){const parsed=JSON.parse(cached);if(parsed&&parsed.name&&!parsed.id)state.companyDraft=normalizeCompany(parsed);}}catch(e){}}state.companyTab=tab;state.paletteSuggestions=[];state.modal='company';renderCompanyModal();}
function captureCompany(){const d=state.companyDraft;if(!d)return;const shared=$('#company-shared');if(shared)d.shared=shared.checked;['name','description','instructions'].forEach(k=>{const el=$(`[name="company-${k}"]`);if(el)d[k]=el.value;});$$('[data-font-role]').forEach(el=>{d.font_roles ||= {};d.font_roles[el.dataset.fontRole]=el.value;});try{localStorage.setItem('studio_company_draft',JSON.stringify(d));}catch(e){}}
function renderCompanyModal(){const d=state.companyDraft;const tab=state.companyTab;const body=`<div class="tabs" role="tablist">${[['identity','Identidade'],['assets','Logos e fontes'],['documents','Documentos'],['instructions','Orientações']].map(([v,n])=>`<button data-action="company-tab" data-tab="${v}" class="${tab===v?'active':''}" role="tab" aria-selected="${tab===v}">${n}</button>`).join('')}</div>${tab==='identity'?companyIdentityHTML(d):tab==='assets'?companyAssetsHTML(d):tab==='documents'?companyDocumentsHTML(d):companyInstructionsHTML(d)}`;showModal(d.id?'Editar empresa':'Adicionar empresa',body,`<span class="tiny muted">Dados permanentes · salvos apenas neste computador</span><div class="row">${btn('Cancelar','close-modal',null,'ghost')}${btn('Salvar empresa','save-company','check','primary')}</div>`,true);updateBrandPreview();}
function companyIdentityHTML(d){return `<div class="grid2"><div class="field"><label for="company-name">Nome da empresa</label><input id="company-name" name="company-name" value="${esc(d.name)}" placeholder="Ex.: Aurora Studio" required maxlength="150"></div><div class="field"><label for="company-description">Descrição <span class="muted">· opcional</span></label><input id="company-description" name="company-description" value="${esc(d.description)}" placeholder="Como você identifica esta empresa" maxlength="500"></div></div><div class="divider"></div><div class="row between"><div><h3 style="margin-bottom:5px">Cores da marca</h3><p class="muted small" style="margin:0">Escolha visualmente. Códigos são opcionais.</p></div>${btn('Adicionar cor','add-color','plus','small')}</div><div id="palette-editor" class="palette-editor" style="margin-top:16px">${paletteHTML()}</div>${!d.colors.length?'<p class="small muted" id="palette-empty">Sem paleta aprovada. A prévia usa cores neutras provisórias.</p>':''}<div class="row wrap" style="margin-top:16px">${btn('Pegar cor do logo','show-eyedropper','eye','small')}${btn('Extrair cores do logo','extract-logo','palette','small')}</div><div id="color-image-area"></div><div id="palette-suggestions"></div><div class="brand-preview" id="brand-preview"></div><p class="tiny muted" style="margin:10px 0 0">A prévia demonstra a identidade. Ela não define o formato, a duração ou o áudio de novos vídeos.</p>`;}
function paletteHTML(){return (state.companyDraft.colors||[]).map((c,i)=>`<div class="color-row" data-color-index="${i}"><input type="color" value="${hex(c.hex)||'#6147CD'}" aria-label="Escolher cor ${i+1}" data-color-field="picker"><input data-color-field="name" value="${esc(c.name||'')}" placeholder="Nome da cor" aria-label="Nome da cor ${i+1}"><select data-color-field="role" aria-label="Função da cor ${i+1}">${[['','Sem função'],['primary','Principal'],['secondary','Secundária'],['accent','Destaque'],['background','Fundo'],['text','Texto']].map(([v,l])=>`<option value="${v}" ${c.role===v?'selected':''}>${l}</option>`).join('')}</select><input data-color-field="hex" value="${hex(c.hex)||'#6147CD'}" aria-label="Código HEX da cor ${i+1}" maxlength="7" placeholder="#000000"><div class="color-actions"><button type="button" data-action="color-up" data-index="${i}" title="Mover para cima">${icon('up')}</button><button type="button" data-action="color-exact" data-index="${i}" title="Editar RGB">${icon('more')}</button><button type="button" data-action="color-remove" data-index="${i}" title="Remover cor">${icon('close')}</button></div><div class="color-exact"><span class="tiny muted">RGB</span>${rgb(c.hex).map((v,j)=>`<input type="number" data-color-field="rgb-${j}" min="0" max="255" value="${v}" aria-label="${['Vermelho','Verde','Azul'][j]}" style="width:64px">`).join('')}<button class="btn ghost small" data-action="copy-color" data-index="${i}">Copiar HEX</button></div></div>`).join('');}
function updateBrandPreview(){const el=$('#brand-preview'),d=state.companyDraft;if(!el||!d)return;const c=(role,fallback)=>hex(d.colors.find(c=>c.role===role)?.hex)||fallback;const bg=c('background','#FFFFFF'),text=c('text','#29272E'),primary=c('primary',hex(d.colors[0]?.hex)||'#6147CD');el.style.background=bg;el.style.color=text;el.innerHTML=`<div class="preview-label">Prévia da identidade ${d.colors.length?'':'· cores provisórias'}</div>${logoAsset(d)?`<img src="${assetURL(logoAsset(d))}" alt="Logo original">`:''}<h3>${esc(d.name||'Sua marca, sua identidade.')}</h3><p>Uma mensagem com espaço para respirar.</p><span class="preview-pill" style="background:${primary};color:${contrastText(primary)}">Cor principal em contexto</span>`;}
function contrastText(h){const [r,g,b]=rgb(h);return (.299*r+.587*g+.114*b)>165?'#1F2025':'#FFFFFF';}
function companyAssetsHTML(d){return `<div class="grid2"><section><h3>Logos e variações aprovadas</h3><div class="dropzone" role="button" tabindex="0" data-drop-kind="logo" data-action="upload-company" data-kind="logo">${icon('upload')}<p>Solte os arquivos ou clique para importar</p><small>PNG, SVG, WebP e JPEG · proporções preservadas</small></div>${assetList(d.assets.filter(a=>a.kind==='logo'))}</section><section><h3>Fontes da empresa</h3><div class="dropzone" role="button" tabindex="0" data-drop-kind="font" data-action="upload-company" data-kind="font">${icon('upload')}<p>Adicionar arquivos de fonte</p><small>TTF, OTF, WOFF2 · use fontes licenciadas</small></div>${assetList(d.assets.filter(a=>a.kind==='font'))}</section></div><div class="divider"></div><h3>Uso das fontes</h3><div class="grid3">${[['heading','Títulos'],['body','Textos'],['caption','Legendas']].map(([r,label])=>`<div class="field"><label>${label}</label><select data-font-role="${r}"><option value="">Escolher depois</option>${d.assets.filter(a=>a.kind==='font').map(a=>`<option value="${esc(a.id)}" ${d.font_roles?.[r]===a.id?'selected':''}>${esc(a.font_family||a.family||a.name)}</option>`).join('')}</select></div>`).join('')}</div><p class="tiny muted" style="margin-top:16px">Fontes ausentes usam uma alternativa neutra identificada na exportação. A integridade, os caracteres e o uso em render precisam passar pela verificação do componente.</p>`;}
function companyDocumentsHTML(d){return `<p class="small muted">Importar mantém uma cópia neste PC. Escolha o tipo para o agente entender a função do documento.</p><div class="row" style="margin-bottom:15px"><div class="field grow"><label>Classificação</label><select id="document-kind"><option value="manual">Manual da marca</option><option value="reference">Referência</option><option value="briefing">Briefing antigo</option></select></div>${btn('Adicionar documentos','upload-company','upload','','data-kind="document" style="margin-top:21px"')}</div><div class="dropzone" role="button" tabindex="0" data-drop-kind="document" data-action="upload-company" data-kind="document">${icon('file')}<p>Solte documentos aqui</p><small>PDF, DOCX, TXT, Markdown e formatos de texto suportados</small></div>${assetList(d.assets.filter(a=>!['logo','font'].includes(a.kind)))}<div class="notice" style="margin-top:15px">Documentos importados são referências consultáveis. Eles não se tornam instruções permanentes nem o briefing de um novo vídeo.</div><details style="margin-top:18px"><summary class="small muted" style="cursor:pointer">Compartilhamento dentro do grupo</summary><label class="row small" style="margin-top:12px;align-items:start"><input type="checkbox" id="company-shared" ${d.shared?'checked':''}><span>Permitir consultar os documentos desta empresa nas outras empresas deste computador.</span></label><p class="tiny muted" style="margin:9px 0 0">Ative somente para materiais comuns ao grupo. A identidade, as instruções permanentes e os projetos continuam vinculados à empresa de origem.</p></details><div class="divider"></div><div class="row between"><h3 style="margin:0">Pastas aprovadas da empresa</h3>${btn('Selecionar pasta','company-folder','folder','small')}</div>${(d.folders||[]).map((p,i)=>`<div class="file-badge"><span class="grow" style="overflow-wrap:anywhere">${esc(typeof p==='string'?p:p.path)}</span><button data-action="remove-company-folder" data-index="${i}" title="Remover pasta">${icon('close')}</button></div>`).join('')}<p class="tiny muted" style="margin-top:13px">Adicionar uma pasta autoriza consultas sob demanda; não inicia indexação do computador inteiro.</p>`;}
function companyInstructionsHTML(d){return `<div class="field"><label>Instruções permanentes</label><textarea name="company-instructions" rows="10" placeholder="Tom de voz, terminologia, regras de identidade, informações que exigem confirmação e restrições de comunicação…">${esc(d.instructions)}</textarea><small>Defina aqui apenas regras duradouras desta empresa.</small></div><div class="notice" style="margin-top:20px">O objetivo, o público, o CTA, a duração, o formato e as escolhas de áudio de cada vídeo serão definidos no projeto. Um briefing antigo não estabelece uma campanha atual.</div>`;}
async function saveCompany(close=true){captureCompany();for(const input of $$('[data-color-field]')){if(input.reportValidity&&!input.reportValidity())throw Error('Revise os valores da paleta antes de salvar.');}const d=state.companyDraft;if(!d.name.trim())throw Error('Informe o nome da empresa para salvar.');if(d.colors.some(c=>!hex(c.hex)))throw Error('Revise as cores: use o seletor ou um HEX válido, como #6147CD.');const r=await api('/companies',{method:'POST',body:d});const saved=r.company||r;d.id=saved.id||d.id;if(!d.id)throw Error('O cadastro não retornou o identificador da empresa.');state.company=d.id;localStorage.setItem('studio_company',d.id);await refresh();const updated=state.data.companies.find(c=>c.id===d.id);if(updated)state.companyDraft=normalizeCompany(updated);if(close){try{localStorage.removeItem('studio_company_draft');}catch(e){}closeModal();render();toast('Empresa salva. As escolhas de vídeo serão feitas em cada projeto.');}return d.id;}
function pickFiles(accept,multiple=true){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.multiple=multiple;input.className='file-input';document.body.append(input);input.addEventListener('change',()=>{resolve([...input.files]);input.remove();},{once:true});input.addEventListener('cancel',()=>{resolve([]);input.remove();},{once:true});input.click();});}
async function uploadCompany(kind,files){captureCompany();if(kind==='document')kind=$('#document-kind')?.value||'reference';if(!state.companyDraft.name.trim())throw Error('Informe o nome da empresa antes de importar seus materiais.');const selected=files||await pickFiles(kind==='logo'?'.png,.jpg,.jpeg,.webp,.svg':kind==='font'?'.ttf,.otf,.woff2':'.pdf,.docx,.txt,.md,.csv,.json,.yaml,.yml,.html');if(!selected.length)return;toast('Importando os arquivos para esta empresa…');const id=await saveCompany(false);for(const file of selected){const form=new FormData();form.set('company_id',id);form.set('kind',kind);form.set('file',file);await api('/upload',{method:'POST',body:form});}await refresh();state.companyDraft=normalizeCompany(state.data.companies.find(c=>c.id===id));renderCompanyModal();toast(`${selected.length} arquivo(s) importado(s).`);}
async function loadLogoCanvas(){captureCompany();const logo=logoAsset(state.companyDraft);if(!logo){toast('Adicione um logo em “Logos e fontes” para escolher suas cores.',true);state.companyTab='assets';renderCompanyModal();return null;}const area=$('#color-image-area');area.innerHTML='<p class="small muted" style="margin:16px 0 8px">Clique em um ponto do logo para adicionar a cor à paleta.</p><div class="canvas-area"><canvas id="logo-canvas" aria-label="Logo: clique para selecionar uma cor"></canvas></div>';const canvas=$('#logo-canvas');const img=new Image();img.src=assetURL(logo);await img.decode();const scale=Math.min(1,600/img.width,300/img.height);canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*canvas.width/r.width),y=Math.floor((e.clientY-r.top)*canvas.height/r.height);const [r1,g,b,a]=ctx.getImageData(Math.min(canvas.width-1,Math.max(0,x)),Math.min(canvas.height-1,Math.max(0,y)),1,1).data;if(a<200){toast('Esse ponto é transparente. Escolha uma parte opaca do logo.');return;}addColor('#'+[r1,g,b].map(n=>n.toString(16).padStart(2,'0')).join(''));toast('Cor adicionada. Revise o nome e a função antes de salvar.');};return {canvas,ctx};}
function addColor(value='#6147CD'){captureCompany();state.companyDraft.colors.push({hex:hex(value)||'#6147CD',name:'Cor '+(state.companyDraft.colors.length+1),role:state.companyDraft.colors.length?'':'primary'});$('#palette-editor').innerHTML=paletteHTML();$('#palette-empty')?.remove();updateBrandPreview();}
async function extractLogo(){const result=await loadLogoCanvas();if(!result)return;const pixels=result.ctx.getImageData(0,0,result.canvas.width,result.canvas.height).data,clusters=new Map();for(let i=0;i<pixels.length;i+=16){if(pixels[i+3]<220)continue;const key=[pixels[i],pixels[i+1],pixels[i+2]].map(v=>Math.round(v/24)).join(',');const bin=clusters.get(key)||{n:0,r:0,g:0,b:0};bin.n++;bin.r+=pixels[i];bin.g+=pixels[i+1];bin.b+=pixels[i+2];clusters.set(key,bin);}const chosen=[];for(const bin of [...clusters.values()].sort((a,b)=>b.n-a.n)){const c=[bin.r,bin.g,bin.b].map(v=>Math.round(v/bin.n));if(chosen.some(x=>Math.sqrt(x.reduce((s,v,i)=>s+(v-c[i])**2,0))<45))continue;chosen.push(c);if(chosen.length===6)break;}state.paletteSuggestions=chosen.map(c=>'#'+c.map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase());$('#palette-suggestions').innerHTML=`<div class="notice" style="margin-top:16px"><strong>Sugestões extraídas do logo</strong><div class="suggestions">${state.paletteSuggestions.map(h=>`<span style="background:${h}" title="${h}"></span>`).join('')}${btn('Adicionar sugestões à paleta','approve-palette','check','small')}</div><p class="tiny" style="margin:10px 0 0">Confira as sugestões antes de salvar. Extrair cores não estabelece regras de marca.</p></div>`;}
function openNewProject(){if(!state.company){toast('Selecione ou cadastre a empresa deste vídeo.');state.view='companies';render();return;}state.projectDraft={company_id:state.company,title:'',briefing:'',aspect:'',duration:'',audio:{mode:''},resolution:'',operations:[],source:'',source_asset_id:'',attachments:[],folder:'',scope:'company'};state.modal='project';renderProjectModal();}
function captureProject(){const d=state.projectDraft;if(!d)return;['title','briefing','duration','resolution','scope'].forEach(k=>{const el=$(`[name="project-${k}"]`);if(el)d[k]=el.value;});const mode=$('[name="project-audio"]');if(mode)d.audio.mode=mode.value;d.operations=$$('[name="operation"]:checked').map(e=>e.value);}
function renderProjectModal(){const d=state.projectDraft;showModal('Novo vídeo · '+(company()?.name||'Empresa'),`<div class="notice" style="margin-bottom:20px">Estas escolhas valem somente para este vídeo. Você pode deixar os detalhes abertos e defini-los na conversa.</div><div class="field"><label>O que vamos criar?</label><textarea name="project-briefing" rows="3" placeholder="Ex.: Transforme esta entrevista em três cortes, com legendas da marca e sem remover pausas importantes.">${esc(d.briefing)}</textarea></div><div class="field" style="margin-top:15px"><label>Nome do projeto <span class="muted">· opcional</span></label><input name="project-title" value="${esc(d.title)}" placeholder="Dê um nome fácil de encontrar" maxlength="180"></div><div class="divider"></div><div class="row between wrap"><h3 style="margin:0">Materiais deste vídeo</h3><div class="row">${btn('Adicionar arquivos','draft-upload','upload','small')}${btn('Selecionar pasta','draft-folder','folder','small')}</div></div><div class="project-source">${d.source?`<div class="file-badge">${icon('film')}<span class="grow">${esc(sourceName(d))}</span></div>`:''}${d.attachments.map(a=>`<div class="file-badge">${icon('file')}${esc(a.name||a.id)}</div>`).join('')}${d.folder?`<div class="file-badge">${icon('folder')}<span style="overflow-wrap:anywhere">${esc(d.folder)}</span></div>`:''}</div><div class="divider"></div><div class="field"><label>Formato</label><div class="choice-grid">${[['9:16','Vertical',''],['16:9','Horizontal','landscape'],['1:1','Quadrado','square'],['4:5','Retrato','portrait'],['source','Original','original']].map(([v,n,c])=>`<button class="aspect-option ${d.aspect===v?'active':''}" data-action="set-aspect" data-value="${v}"><span class="aspect-icon ${c}"></span><span>${n}</span><span class="tiny">${v==='source'?'Manter fonte':v}</span></button>`).join('')}</div><small>${d.aspect?'Seleção deste projeto: '+esc(d.aspect==='source'?'preservar o arquivo original':d.aspect):'Ainda não definido. O agente pode sugerir a partir do pedido.'}</small></div><div class="grid2" style="margin-top:18px"><div class="field"><label>Duração</label><select name="project-duration"><option value="">Definir na conversa</option>${[['source','Preservar duração original'],['suggest','Pedir uma sugestão'],['15','15 segundos'],['30','30 segundos'],['60','60 segundos'],['custom','Informar outra duração no briefing']].map(([v,n])=>`<option value="${v}" ${d.duration===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Resolução</label><select name="project-resolution"><option value="">Definir na conversa</option>${[['source','Preservar original'],['1080','1080p'],['720','720p'],['2160','4K · sujeito aos recursos disponíveis']].map(([v,n])=>`<option value="${v}" ${d.resolution===v?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="field" style="margin-top:17px"><label>Áudio neste vídeo</label><select name="project-audio"><option value="">Definir na conversa</option>${[['original','Manter áudio original'],['none','Sem áudio'],['music','Usar uma trilha fornecida'],['narration','Usar uma narração fornecida'],['mix','Combinar original, trilha e/ou narração']].map(([v,n])=>`<option value="${v}" ${d.audio.mode===v?'selected':''}>${n}</option>`).join('')}</select></div><div id="audio-fields">${audioFieldsHTML(d)}</div><div class="divider"></div><h3>O que fazer com os materiais?</h3><div class="operation-grid">${[['captions','Legendar'],['silence','Remover pausas'],['clips','Sugerir cortes'],['reframe','Ajustar formato'],['audio','Melhorar áudio'],['motion','Adicionar animações']].map(([v,n])=>`<label class="check-card"><input name="operation" type="checkbox" value="${v}" ${d.operations.includes(v)?'checked':''}>${n}</label>`).join('')}</div><details style="margin-top:18px"><summary class="small muted" style="cursor:pointer">Acesso aos arquivos deste projeto</summary><div class="field" style="margin-top:12px"><select name="project-scope">${[['files','Somente os arquivos importados'],['company','Arquivos importados e pastas aprovadas da empresa'],['folder','Somente a pasta selecionada'],['computer','Arquivos acessíveis ao usuário deste Windows']].map(([v,n])=>`<option value="${v}" ${d.scope===v?'selected':''}>${n}</option>`).join('')}</select><small>O acesso amplo permite leitura sob demanda. Não indexa todo o PC nem contorna permissões do Windows.</small></div></details>`,`${btn('Cancelar','close-modal',null,'ghost')}${btn('Criar projeto','create-project','arrow','primary')}`,false);}
function audioFieldsHTML(d){if(['music','narration','mix'].includes(d.audio.mode))return `<div class="row wrap" style="margin-top:12px">${['music','mix'].includes(d.audio.mode)?btn(d.audio.music_path?'Trilha adicionada':'Adicionar trilha','draft-audio','upload','small','data-kind="music"'):''}${['narration','mix'].includes(d.audio.mode)?btn(d.audio.narration_path?'Narração adicionada':'Adicionar narração','draft-audio','upload','small','data-kind="narration"'):''}</div><p class="tiny muted" style="margin:10px 0 0">Use arquivos de áudio aprovados. Nenhuma música ou voz será adicionada automaticamente.</p>`;return '';}
async function uploadProjectDraft(kind){captureProject();const files=await pickFiles(kind?'audio/*': 'video/*,audio/*,image/*,.srt,.vtt,.txt,.pdf,.docx',!kind);for(const file of files){const fd=new FormData();fd.set('company_id',state.company);fd.set('kind','file');fd.set('file',file);const a=await api('/upload',{method:'POST',body:fd});if(kind){state.projectDraft.audio[kind+'_path']=a.path;state.projectDraft.attachments.push(a);}else if(!state.projectDraft.source&&file.type.startsWith('video/')){state.projectDraft.source=a.path;state.projectDraft.source_asset_id=a.id;state.projectDraft.source_name=a.name||file.name;}else state.projectDraft.attachments.push(a);}renderProjectModal();}
async function createProject(){captureProject();const d=state.projectDraft;if(d.scope==='folder'&&!d.folder)throw Error('Selecione a pasta deste projeto ou escolha outro tipo de acesso.');if(!d.title.trim())d.title=d.briefing.trim().slice(0,65)||'Novo vídeo';const p=await api('/projects',{method:'POST',body:{...d,attachments:d.attachments.map(a=>typeof a==='string'?a:a.id)}});closeModal();await refresh();await openProject(p.id);toast('Projeto criado. As escolhas foram salvas somente neste vídeo.');}
async function openProject(id){state.project=await api('/projects/'+encodeURIComponent(id));state.company=state.project.company_id;localStorage.setItem('studio_company',state.company);state.messages=state.project.messages||[];state.view='chat';render();await loadJobs();}
function scrollChat(){const e=$('#messages');if(e)e.scrollTop=e.scrollHeight;}
async function sendChat(message){if(state.chatBusy||!message.trim())return;if(!company())throw Error('Selecione uma empresa antes de conversar.');if(!state.project){state.chatBusy=true;try{state.project=await api('/projects',{method:'POST',body:{company_id:state.company,title:'Conversa · '+new Date().toLocaleDateString('pt-BR'),briefing:'',aspect:'',duration:'',audio:{mode:''},resolution:'',scope:'company',operations:[],attachments:[]}});}catch(e){state.chatBusy=false;throw e;}}state.chatBusy=true;state.messages.push({role:'user',content:message});const assistant={role:'assistant',content:''};state.messages.push(assistant);render();const messages=$('#messages');let response;try{state.chatAbort=new AbortController();response=await fetch('/api/chat',{method:'POST',signal:state.chatAbort.signal,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({company_id:state.company,project_id:state.project?.id||'',message})});if(!response.ok){const err=await response.json().catch(()=>({error:'Falha ao conversar com o modelo.'}));throw Error(err.error||err.message);}if((response.headers.get('content-type')||'').includes('application/json')&&!(response.headers.get('content-type')||'').includes('ndjson')){const r=await response.json();assistant.content=r.content||r.message||r.response||'';}else{const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';const handle=line=>{if(!line.trim())return;let v;try{v=JSON.parse(line.replace(/^data:\s*/,''));}catch{return;}if(v.type==='delta')assistant.content+=v.text||v.content||'';else if(v.type==='error')throw Error(v.error||v.message||'O agente encontrou um erro.');else if(v.type==='tool'){const el=document.createElement('div');el.className='message-tool';el.textContent=v.message||v.name||v.tool||'Executando ferramenta…';messages?.append(el);}else if(v.type==='done'&&v.content&&!assistant.content)assistant.content=v.content;const all=$$('.message.assistant',messages);const current=all.at(-1);if(current){current.innerHTML='<span class="speaker">Estúdio Local</span>'+renderText(assistant.content||'…');scrollChat();}};while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let i;while((i=buffer.indexOf('\n'))!==-1){handle(buffer.slice(0,i));buffer=buffer.slice(i+1);}}if(buffer.trim())handle(buffer);}if(!assistant.content)assistant.content='A solicitação foi processada. Veja as etapas e arquivos do projeto.';}catch(e){if(e.name==='AbortError'){assistant.content+=(assistant.content?'\n\n':'')+'Resposta interrompida.';}else{assistant.content+=(assistant.content?'\n\n':'')+'Não consegui concluir: '+e.message;toast(e.message,true);}}finally{state.chatBusy=false;state.chatAbort=null;render();if(state.project)await loadJobs();}}
function resultFilesHTML(result){result={...result,...(typeof result.captions==='object'?result.captions:{})};const labels={srt:'Legendas SRT',vtt:'Legendas VTT',ass:'Legendas ASS',captions_json:'Tempos das legendas',transcript_path:'Transcrição JSON',timeline:'Mapa de edição',motion_project:'Composição editável'};const items=Object.entries(labels).filter(([k])=>typeof result[k]==='string').map(([k,n])=>[n,result[k]]);const fileURL=p=>'/api/file?project_id='+encodeURIComponent(state.project.id)+'&path='+encodeURIComponent(p);const frames=Array.isArray(result.frames)?result.frames:[];const images=Array.isArray(result.images)?result.images:[];return `${result.preview_image?`<a href="${fileURL(result.preview_image)}" target="_blank" rel="noopener"><img class="media-preview" src="${fileURL(result.preview_image)}" alt="Prévia gerada" style="object-fit:contain"></a>`:''}${items.length?`<div class="quick-actions">${items.map(([n,p])=>`<a class="chip" href="${fileURL(p)}" target="_blank" rel="noopener">${n}</a>`).join('')}</div>`:''}${[...frames,...images].length?`<div class="result-thumbnails">${[...frames,...images].slice(0,12).map(f=>{const path=typeof f==='string'?f:f.path;return path?`<a href="${fileURL(path)}" target="_blank" rel="noopener"><img src="${fileURL(path)}" alt="Fotograma ou slide gerado" loading="lazy"></a>`:''}).join('')}</div>`:''}${result.warnings?.length?`<div class="notice warning" style="margin-top:10px">${esc(result.warnings.join(' '))}</div>`:''}`;}
function transcriptHTML(data){return `<div class="notice" style="margin-bottom:18px">Corrija o texto e, se necessário, os tempos de cada trecho. Alterações preservam uma revisão do projeto. A precisão por palavra precisa ser revisada após editar o texto.</div><div class="transcript-segments">${(data.segments||[]).map((s,i)=>`<section class="transcript-segment" data-transcript-segment="${i}"><div class="row between"><strong class="small">Trecho ${i+1}</strong><div class="row small"><label>Início <input type="number" step="0.01" min="0" data-time="start" value="${Number(s.start).toFixed(2)}" aria-label="Início do trecho ${i+1} em segundos"></label><span>→</span><label>Fim <input type="number" step="0.01" min="0" data-time="end" value="${Number(s.end).toFixed(2)}" aria-label="Fim do trecho ${i+1} em segundos"></label><span class="muted">s</span></div></div><textarea rows="2" aria-label="Texto do trecho ${i+1}">${esc(s.text)}</textarea></section>`).join('')}</div>`;}
function jobsHTML(jobs){if(!jobs.length)return '<p class="small muted" style="margin:15px 0 0">Nenhuma etapa executada ainda.</p>';return jobs.map(j=>{const done=['completed','done','success'].includes(j.status),failed=['failed','error','interrupted','cancelled'].includes(j.status),running=['pending','queued','running','waiting'].includes(j.status);const output=j.output||j.result||{};const path=output.output||j.output_path||(['edit','motion'].includes(j.action)?output.path:'');const video=path&&/\.(mp4|webm|mov)$/i.test(path);return `<article class="job"><div class="row between"><h4>${esc(j.label||({probe:'Inspeção do vídeo',transcribe:'Transcrição',plan_silence:'Proposta de cortes',captions:'Legendas',edit:'Exportação',motion:'Animação',frames:'Fotogramas',carousel:'Carrossel'})[j.action]||j.action||'Etapa')}</h4>${done?'<span class="status-success">✓</span>':failed?'<span class="status-error">!</span>':''}</div><p>${esc(j.message||j.stage||({queued:'Na fila',running:'Em execução',completed:'Concluído',failed:'Falhou',cancelled:'Cancelado'})[j.status]||j.status)}</p>${j.error?`<div class="notice error small">${esc(j.error)}</div>`:''}${running&&Number.isFinite(j.progress)?`<div class="progress-track"><div class="progress-bar" style="width:${percent(j.progress)}%"></div></div>`:running?'<div class="job-unknown"><span class="spinner"></span> Aguarde a etapa atual</div>':''}${video?`<video class="media-preview" controls preload="metadata" src="/api/file?project_id=${encodeURIComponent(state.project.id)}&path=${encodeURIComponent(path)}"></video>`:''}${resultFilesHTML(output)}<div class="row wrap" style="margin-top:8px">${running?btn('Cancelar','cancel-job','close','ghost small',`data-id="${esc(j.id)}"`):''}${failed?btn('Tentar de novo','retry-job','refresh','small',`data-id="${esc(j.id)}"`):''}${path?`<a class="btn small" href="/api/file?project_id=${encodeURIComponent(state.project.id)}&path=${encodeURIComponent(path)}" target="_blank" rel="noopener">${icon('download')}Abrir resultado</a>`:''}${output.transcript_path||path&&/transcript.*\.json$/i.test(path)?btn('Editar transcrição','edit-transcript','edit','small',`data-path="${esc(output.transcript_path||path)}"`):''}${done&&output.motion_project?btn('Prévia interativa','motion-player','play','small',`data-id="${esc(j.id)}"`):''}${j.output_dir?btn('Abrir pasta','open-path','folder','small',`data-path="${esc(j.output_dir)}"`):''}${done&&j.action==='plan_silence'?btn('Revisar proposta','view-job-result','eye','small',`data-id="${esc(j.id)}"`):''}</div></article>`;}).join('');}
async function showMotionPlayer(id){const job=state.jobs.find(j=>j.id===id),result=job?.result||job?.output;if(!result?.motion_project)throw Error('Esta etapa ainda não possui uma composição para visualizar.');const r=await fetch('/api/file?project_id='+encodeURIComponent(state.project.id)+'&path='+encodeURIComponent(result.motion_project));if(!r.ok)throw Error('Não foi possível abrir a composição da prévia.');const data=await r.json();state.modal='motion-player';showModal('Prévia interativa da animação',`<p class="small muted">Reproduza, pause e percorra os quadros da composição. Os arquivos MP4 e a imagem de prévia continuam disponíveis no projeto.</p><iframe id="motion-player" title="Player da animação" src="/api/player/player.html" style="width:100%;height:520px;border:0;background:#19171d;border-radius:12px" allow="autoplay"></iframe>`,btn('Fechar','close-modal',null,'primary'),true);const listener=event=>{const frame=$('#motion-player');if(event.origin!==location.origin||!frame||event.source!==frame.contentWindow||event.data?.type!=='motion-player-ready')return;frame.contentWindow.postMessage({type:'motion-preview',props:{...data,assetBase:'/api/job-assets/'+encodeURIComponent(job.id)}},location.origin);};window.addEventListener('message',listener);state.playerCleanup=()=>window.removeEventListener('message',listener);}
async function loadJobs(){if(!state.project)return;const jobs=await api('/jobs?project_id='+encodeURIComponent(state.project.id));state.jobs=Array.isArray(jobs)?jobs:jobs.jobs||[];const area=$('#jobs-area');if(area)area.innerHTML=jobsHTML(state.jobs);}
async function runJob(action){if(!state.project)throw Error('Crie ou abra um projeto para executar esta ação.');const options={};if(action==='motion'){const text=prompt('Texto principal da animação deste projeto:',state.project.briefing||'');if(text===null)return;options.title=text;}if(action==='captions')options.burn=false;const job=await api('/jobs',{method:'POST',body:{project_id:state.project.id,action,options}});toast('Etapa adicionada ao projeto.');await loadJobs();}
async function loadMemories(){if(!state.company){state.memory=[];return;}const r=await api('/memories?company_id='+encodeURIComponent(state.company));state.memory=Array.isArray(r)?r:r.memories||[];}
function editMemory(id){if(!state.company)throw Error('Selecione uma empresa para guardar a memória.');const m=state.memory.find(x=>x.id===id)||{content:'',scope:'company'};state.modal='memory';state.editingMemory=id||'';showModal(id?'Editar memória':'Adicionar memória',`<div class="field"><label>O que o agente deve lembrar?</label><textarea id="memory-content" rows="5">${esc(m.content||m.text||'')}</textarea></div><div class="field" style="margin-top:15px"><label>Escopo</label><select id="memory-scope">${m.project_id?'<option value="project">Projeto associado (preservado)</option>':`<option value="company" ${m.scope==='company'?'selected':''}>Empresa: ${esc(company().name)}</option><option value="personal" ${m.scope==='personal'?'selected':''}>Pessoal · todas as empresas</option>`}</select></div><p class="small muted" style="margin:15px 0 0">Memórias pessoais podem aparecer em todas as empresas. Não salve senhas. Detalhes de um vídeo ficam no próprio projeto.</p>`,`${btn('Cancelar','close-modal',null,'ghost')}${btn('Salvar memória','save-memory','check','primary')}`);}
async function showDiagnostics(){state.diagnostics=await api('/diagnostics');const d=state.diagnostics;showModal('Diagnóstico do computador',`<p class="small muted">Resultados fornecidos pelo próprio aplicativo. Compatibilidade final depende dos componentes instalados.</p><div class="diagnostic-list">${Object.entries(d).map(([k,v])=>`<div class="diagnostic-line"><span>${esc(({os:'Sistema',gpu:'GPU',free_bytes:'Espaço livre',ram:'Memória',ollama:'Modelo local',ffmpeg:'FFmpeg',remotion:'Remotion',transcription:'Transcrição',platform:'Plataforma'})[k]||k)}</span><span>${esc(typeof v==='object'?JSON.stringify(v,null,2):v)}</span></div>`).join('')}</div>`,`${btn('Fechar','close-modal',null,'ghost')}${btn('Salvar diagnóstico','export-diagnostics','download','primary')}`);}
function downloadJSON(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openCompanyExport(){if(!company())throw Error('Selecione uma empresa para exportar.');state.modal='company-export';showModal('Exportar '+company().name,`<p class="small muted">O pacote leva o nome, as cores e as orientações permanentes. Escolha quais arquivos incluir.</p><label class="check-card"><input type="checkbox" id="bundle-assets"> Incluir logos, fontes, manuais e referências da empresa</label><label class="check-card" style="margin-top:10px"><input type="checkbox" id="bundle-media" disabled> Incluir também mídias importadas para projetos</label><div class="notice" style="margin-top:18px">Mídias podem aumentar bastante o pacote. Projetos, conversas, memórias e autorizações de pastas não são transferidos. O limite do pacote é 512 MB comprimidos e 1 GB expandido.</div>`,`${btn('Somente cadastro JSON','export-company-json','file','ghost small')}${btn('Baixar pacote ZIP','download-company-bundle','download','primary')}`);}
async function downloadCompanyBundle(){const c=company();if(!c)throw Error('Selecione uma empresa.');const assets=Boolean($('#bundle-assets')?.checked),media=assets&&Boolean($('#bundle-media')?.checked);const query=new URLSearchParams({company_id:c.id,include_assets:assets?'1':'0',include_project_media:media?'1':'0'});toast('Preparando o pacote de empresa…');const r=await fetch('/api/company-bundle?'+query,{credentials:'same-origin'});if(!r.ok){const e=await r.json().catch(()=>({error:'Não foi possível exportar a empresa.'}));throw Error(e.error);}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='empresa-'+c.name.replace(/[^a-z0-9_-]/gi,'-')+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeModal();toast(assets?'Pacote com os arquivos selecionados pronto para salvar.':'Cadastro exportado sem arquivos de marca ou de projetos.');}
async function previewCompanyZIP(file){if(file.size>512*1024*1024)throw Error('Este ZIP ultrapassa 512 MB. Exporte um pacote menor.');const tail=new Uint8Array(await file.slice(Math.max(0,file.size-65557)).arrayBuffer()),view=new DataView(tail.buffer);let end=-1;for(let i=tail.length-22;i>=0;i--){if(view.getUint32(i,true)===0x06054b50){end=i;break;}}if(end<0)throw Error('O arquivo não é um pacote ZIP válido.');const size=view.getUint32(end+12,true),offset=view.getUint32(end+16,true);if(size>4*1024*1024||offset+size>file.size)throw Error('Estrutura do pacote inválida ou grande demais.');const central=new Uint8Array(await file.slice(offset,offset+size).arrayBuffer()),dv=new DataView(central.buffer);let entry=null;for(let i=0;i+46<=central.length;){if(dv.getUint32(i,true)!==0x02014b50)break;const nameLen=dv.getUint16(i+28,true),extraLen=dv.getUint16(i+30,true),commentLen=dv.getUint16(i+32,true),name=new TextDecoder().decode(central.slice(i+46,i+46+nameLen));if(name==='company.json')entry={method:dv.getUint16(i+10,true),compressed:dv.getUint32(i+20,true),expanded:dv.getUint32(i+24,true),offset:dv.getUint32(i+42,true),flags:dv.getUint16(i+8,true)};i+=46+nameLen+extraLen+commentLen;}if(!entry)throw Error('O ZIP não contém company.json. Use um pacote exportado pelo Estúdio Local.');if(entry.expanded>2*1024*1024||entry.compressed>2*1024*1024||(entry.flags&1))throw Error('O cadastro do pacote é muito grande ou está criptografado.');const header=new DataView(await file.slice(entry.offset,entry.offset+30).arrayBuffer());if(header.byteLength<30||header.getUint32(0,true)!==0x04034b50)throw Error('Cabeçalho do pacote inválido.');const start=entry.offset+30+header.getUint16(26,true)+header.getUint16(28,true);if(start+entry.compressed>file.size)throw Error('Pacote incompleto.');const compressed=file.slice(start,start+entry.compressed);let bytes;if(entry.method===0){bytes=new Uint8Array(await compressed.arrayBuffer());}else if(entry.method===8){let stream;try{stream=compressed.stream().pipeThrough(new DecompressionStream('deflate-raw'));}catch{throw Error('Este navegador não consegue visualizar o pacote. Atualize o navegador ou importe o cadastro JSON.');}const reader=stream.getReader(),chunks=[];let total=0;while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>2*1024*1024){await reader.cancel();throw Error('O cadastro expandido excede o limite seguro.');}chunks.push(value);}bytes=new Uint8Array(total);let at=0;for(const chunk of chunks){bytes.set(chunk,at);at+=chunk.length;}}else throw Error('Compressão não suportada. Use um ZIP exportado pelo aplicativo.');const manifest=JSON.parse(new TextDecoder().decode(bytes));if(manifest.format!=='estudio-local-company'||!manifest.company?.name)throw Error('O ZIP não contém um cadastro reconhecido.');return manifest;}
async function importCompanyFile(){const [file]=await pickFiles('.json,.zip',false);if(!file)return;if(file.name.toLowerCase().endsWith('.zip')){const manifest=await previewCompanyZIP(file);state.pendingCompanyBundle=file;state.modal='company-import';const assets=Array.isArray(manifest.assets)?manifest.assets:[];showModal('Importar empresa',`<h3>${esc(manifest.company.name)}</h3><p class="small muted">${esc(file.name)} · ${(file.size/1048576).toFixed(1)} MB</p><div class="grid3"><div class="hardware-item"><span class="label">Cores</span><strong>${manifest.company.colors?.length||0}</strong></div><div class="hardware-item"><span class="label">Arquivos</span><strong>${assets.length}</strong></div><div class="hardware-item"><span class="label">Orientações</span><strong>${manifest.company.instructions?'Incluídas':'Não incluídas'}</strong></div></div>${assets.length?`<details style="margin-top:16px"><summary class="small">Ver arquivos incluídos</summary><div class="upload-list">${assets.slice(0,100).map(a=>`<div class="asset-row">${icon('file')}<span class="grow">${esc(a.name)}</span><span class="tiny muted">${esc(kindLabels[a.kind]||a.kind)}</span></div>`).join('')}${assets.length>100?'<p class="tiny muted">Mais arquivos serão validados durante a importação.</p>':''}</div></details>`:''}<div class="notice" style="margin-top:18px">Será criado um novo cadastro, com os arquivos incluídos copiados para este computador. Empresas existentes serão preservadas. O pacote não concede acesso a pastas e não traz conversas, memórias ou configurações de vídeos.</div><p class="tiny muted" style="margin-top:12px">Esta é uma prévia local. A integridade e os arquivos serão verificados antes de concluir.</p>`,`${btn('Cancelar','close-modal',null,'ghost')}${btn('Importar como nova empresa','confirm-company-import','upload','primary')}`);return;}const payload=JSON.parse(await file.text()),c=payload.company||payload;if(!c.name)throw Error('O arquivo não contém um cadastro válido.');state.companyDraft={...newDraft(),name:c.name,description:c.description||'',instructions:c.instructions||'',colors:(c.colors||[]).filter(x=>hex(x.hex)),assets:[],folders:[]};state.companyTab='identity';state.modal='company';renderCompanyModal();toast('Cadastro carregado para revisão. Logos, fontes e documentos precisam ser importados nesta instalação.');}
async function confirmCompanyImport(){if(!state.pendingCompanyBundle)throw Error('Selecione novamente o pacote.');const form=new FormData();form.set('file',state.pendingCompanyBundle);toast('Validando e importando a empresa…');const r=await api('/company-bundle/import',{method:'POST',body:form});state.pendingCompanyBundle=null;state.company=r.company?.id||'';localStorage.setItem('studio_company',state.company);await refresh();closeModal();render();toast(`Empresa importada com ${r.imported_assets||0} arquivo(s).`);if(r.warnings?.length)showModal('Empresa importada — confira os avisos',`<div class="notice warning">${esc(r.warnings.join('\n'))}</div>`,btn('Entendi','close-modal',null,'primary'));}

async function startSetup(retry=false){if(!retry&&!$('#license-ack')?.checked)throw Error('Leia as condições do Remotion e marque a confirmação para continuar.');const r=await api('/setup',{method:'POST',body:{data_dir:state.setupFolder||state.data.data_dir||'',remotion_license_ack:true,modules:['core'],retry}});state.setupStatus=r;state.setupStep=3;renderSetup();await pollSetup();}
async function pollSetup(){state.setupStatus=await api('/setup/status');if($('#setup-progress-card'))$('#setup-progress-card').innerHTML=setupStatusHTML();if(['completed','ready','done'].includes(state.setupStatus.status)){await refresh();}}
async function backup(){const r=await fetch('/api/backup',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok){const e=await r.json().catch(()=>({error:'Não foi possível criar o backup.'}));throw Error(e.error);}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='backup-estudio-local-'+new Date().toISOString().slice(0,10)+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup dos cadastros disponível. Mídias e fontes originais não estão incluídas; memórias antigas podem constar no arquivo.');}
async function nav(view){if(state.chatBusy&&view!=='chat'){toast('A resposta continua em andamento. Aguarde a conclusão antes de mudar de tela.');return;}state.view=view;if(view!=='chat'){state.project=null;state.messages=[];}if(view==='memory')await loadMemories();if(view==='documents')state.results=null;render();}
async function selectCompany(id){if(state.chatBusy)throw Error('Aguarde a resposta atual antes de trocar de empresa.');state.company=id;localStorage.setItem('studio_company',id);state.project=null;state.messages=[];state.results=null;if(state.view==='memory')await loadMemories();render();}
async function action(el){const a=el.dataset.action;switch(a){case 'nav':await nav(el.dataset.view);break;case 'new-company':await openCompany();break;case 'edit-company':await openCompany(el.dataset.id,el.dataset.tab||'identity');break;case 'select-company':await selectCompany(el.dataset.id);if(!state.data.installed)await openCompany(el.dataset.id);break;case 'close-modal':closeModal();break;case 'company-tab':captureCompany();state.companyTab=el.dataset.tab;renderCompanyModal();break;case 'save-company':await saveCompany();break;case 'upload-company':await uploadCompany(el.dataset.kind);break;case 'add-color':addColor();break;case 'color-remove':captureCompany();state.companyDraft.colors.splice(+el.dataset.index,1);$('#palette-editor').innerHTML=paletteHTML();updateBrandPreview();break;case 'color-up':{captureCompany();const i=+el.dataset.index,colors=state.companyDraft.colors;if(i>0)[colors[i-1],colors[i]]=[colors[i],colors[i-1]];$('#palette-editor').innerHTML=paletteHTML();updateBrandPreview();break;}case 'color-exact':el.closest('.color-row').classList.toggle('exact');break;case 'copy-color':await navigator.clipboard.writeText(state.companyDraft.colors[+el.dataset.index].hex);toast('Código HEX copiado.');break;case 'show-eyedropper':await loadLogoCanvas();break;case 'extract-logo':await extractLogo();break;case 'approve-palette':state.paletteSuggestions.forEach(h=>addColor(h));$('#palette-suggestions').innerHTML='<p class="small status-success">Sugestões adicionadas. Revise os nomes e funções antes de salvar a empresa.</p>';state.paletteSuggestions=[];break;case 'company-folder':{captureCompany();const r=await api('/pick',{method:'POST',body:{kind:'folder',company_id:state.companyDraft.id||''}});if(r.path){state.companyDraft.folders.push(r.path);renderCompanyModal();}break;}case 'remove-company-folder':captureCompany();state.companyDraft.folders.splice(+el.dataset.index,1);renderCompanyModal();break;case 'delete-company':if(company()&&confirm(`Excluir o cadastro de ${company().name}? Revise os projetos vinculados e faça backup antes de continuar.`)){await api('/companies/'+encodeURIComponent(state.company),{method:'DELETE'});state.company='';await refresh();render();toast('Empresa excluída.');}break;case 'export-company':openCompanyExport();break;case 'download-company-bundle':await downloadCompanyBundle();break;case 'export-company-json':if(company()){downloadJSON('empresa-'+company().name.replace(/[^a-z0-9_-]/gi,'-')+'.json',{format:'estudio-local-company-v1',company:{name:company().name,description:company().description,instructions:company().instructions,colors:company().colors},notice:'No asset files, project settings or folder permissions included.'});closeModal();}break;case 'import-company':await importCompanyFile();break;case 'confirm-company-import':await confirmCompanyImport();break;case 'setup-next':state.setupStep=Math.min(2,state.setupStep+1);renderSetup();break;case 'setup-back':state.setupStep=Math.max(0,state.setupStep-1);renderSetup();break;case 'pick-data':{const r=await api('/pick',{method:'POST',body:{kind:'folder',purpose:'data_dir'}});if(r.path){state.setupFolder=r.path;renderSetup();}break;}case 'start-install':await startSetup();break;case 'retry-setup':await startSetup(true);break;case 'cancel-setup':await api('/setup/cancel',{method:'POST',body:{}});await pollSetup();toast('Interrupção solicitada. O componente atual será encerrado com segurança.');break;case 'refresh-setup':await pollSetup();break;case 'finish-setup':await refresh();render();break;case 'diagnostics':await showDiagnostics();break;case 'export-diagnostics':downloadJSON('diagnostico-estudio-local.json',await api('/diagnostics?export=1'));break;case 'new-project':openNewProject();break;case 'set-aspect':captureProject();state.projectDraft.aspect=el.dataset.value;renderProjectModal();break;case 'draft-upload':await uploadProjectDraft();break;case 'draft-audio':await uploadProjectDraft(el.dataset.kind);break;case 'draft-folder':{captureProject();const r=await api('/pick',{method:'POST',body:{kind:'folder',company_id:state.company}});if(r.path){state.projectDraft.folder=r.path;state.projectDraft.scope='folder';renderProjectModal();}break;}case 'create-project':await createProject();break;case 'open-project':await openProject(el.dataset.id);break;case 'project-details':{const p=state.project;showModal('Detalhes deste vídeo',`<div class="notice">Estas informações pertencem apenas ao projeto <strong>${esc(p.title)}</strong>.</div><div class="diagnostic-list">${Object.entries({briefing:p.briefing,aspect:p.aspect,duration:p.duration,audio:p.audio,resolution:p.resolution,scope:p.scope,folder:p.folder,brand_version:p.brand?.version??p.brand_version}).map(([k,v])=>`<div class="diagnostic-line"><span>${esc(({briefing:'Briefing',aspect:'Formato',duration:'Duração',audio:'Áudio',resolution:'Resolução',scope:'Acesso',folder:'Pasta',brand_version:'Versão da marca'})[k])}</span><span>${esc(v?(typeof v==='object'?JSON.stringify(v):v):'A definir')}</span></div>`).join('')}</div><p class="small muted" style="margin-top:15px">Peça ajustes na conversa para revisar o plano antes de executar.</p>`,`${btn('Aplicar identidade atual da empresa','migrate-brand','refresh','small')}${btn('Fechar','close-modal',null,'primary')}`);break;}case 'migrate-brand':{const c=company(),p=state.project;if(!c||!p)throw Error('Abra o projeto de uma empresa.');if(confirm('Aplicar a identidade atual de '+c.name+' (versão '+(c.version||'atual')+') a este projeto? A identidade anterior ficará no histórico. Briefing, duração, formato e áudio deste vídeo serão preservados.')){await api('/projects/'+encodeURIComponent(p.id),{method:'PUT',body:{use_latest_brand:true}});closeModal();await openProject(p.id);toast('Identidade atual aplicada somente a este projeto.');}break;}case 'project-upload':{const files=await pickFiles('video/*,audio/*,image/*,.srt,.vtt,.txt,.pdf,.docx');let current=state.project;const attachments=[...(current.attachments||[])];let update={};for(const f of files){const fd=new FormData();fd.set('company_id',state.company);fd.set('project_id',current.id);fd.set('kind','file');fd.set('file',f);const asset=await api('/upload',{method:'POST',body:fd});attachments.push(asset.id);if((f.type.startsWith('video/')||f.type.startsWith('audio/'))&&(!current.source||confirm('Usar '+f.name+' como arquivo principal deste vídeo? A fonte anterior será preservada.'))){update.source=asset.path;update.source_asset_id=asset.id;current={...current,...update};}}if(files.length){await api('/projects/'+encodeURIComponent(current.id),{method:'PUT',body:{...update,attachments}});toast('Arquivo(s) adicionado(s) ao projeto.');await refresh();await openProject(current.id);}break;}case 'suggest':$('#chat-input').value=el.dataset.text;$('#chat-input').focus();break;case 'stop-chat':state.chatAbort?.abort();break;case 'run-job':await runJob(el.dataset.job);break;case 'retry-job':{const previous=state.jobs.find(j=>j.id===el.dataset.id);if(!previous)throw Error('Atualize as etapas para tentar novamente.');await api('/jobs',{method:'POST',body:{project_id:previous.project_id||state.project.id,action:previous.action,options:previous.options||{}}});await loadJobs();toast('Nova tentativa criada com as mesmas opções.');break;}case 'refresh-jobs':await loadJobs();break;case 'cancel-job':await api('/jobs/'+encodeURIComponent(el.dataset.id)+'/cancel',{method:'POST',body:{}});await loadJobs();break;case 'motion-player':await showMotionPlayer(el.dataset.id);break;case 'view-job-result':{const j=state.jobs.find(j=>j.id===el.dataset.id);showModal('Proposta de edição',`<p class="small muted">Revise os intervalos antes de pedir a exportação. O arquivo original permanece preservado.</p><pre class="setup-log">${esc(JSON.stringify(j.result||j.output,null,2))}</pre>`,`${btn('Fechar','close-modal',null,'ghost')}${btn('Pedir revisão na conversa','review-edit','chat','primary')}`);break;}case 'review-edit':closeModal();$('#chat-input').value='Explique a proposta de cortes e me ajude a revisar os intervalos antes de exportar.';$('#chat-input').focus();break;case 'edit-transcript':{state.transcriptPath=el.dataset.path;const r=await fetch('/api/file?project_id='+encodeURIComponent(state.project.id)+'&path='+encodeURIComponent(state.transcriptPath));if(!r.ok)throw Error('Não foi possível abrir a transcrição.');state.transcriptDraft=await r.json();state.transcriptOriginal=structuredClone(state.transcriptDraft);state.modal='transcript';showModal('Revisar transcrição',transcriptHTML(state.transcriptDraft),`${btn('Cancelar','close-modal',null,'ghost')}${btn('Salvar revisão','save-transcript','check','primary')}`,true);break;}case 'save-transcript':{const draft=state.transcriptDraft;$$('[data-transcript-segment]').forEach(row=>{const i=+row.dataset.transcriptSegment,seg=draft.segments[i],original=state.transcriptOriginal.segments[i],text=row.querySelector('textarea').value.trim(),start=Number(row.querySelector('[data-time=start]').value),end=Number(row.querySelector('[data-time=end]').value);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start)throw Error('Revise os tempos do trecho '+(i+1)+'. O fim deve ser maior que o início.');if(text!==original.text||start!==original.start||end!==original.end)seg.words=[];Object.assign(seg,{text,start,end});});await api('/projects/'+encodeURIComponent(state.project.id)+'/transcript',{method:'POST',body:{path:state.transcriptPath,transcript:draft}});closeModal();toast('Revisão da transcrição salva. Trechos alterados terão o alinhamento por palavra recalculado de forma aproximada.');break;}case 'new-memory':editMemory();break;case 'edit-memory':editMemory(el.dataset.id);break;case 'save-memory':{const content=$('#memory-content').value.trim();if(!content)throw Error('Escreva o conteúdo da memória.');await api('/memories',{method:'POST',body:{id:state.editingMemory,company_id:state.company,text:content,project_id:state.memory.find(m=>m.id===state.editingMemory)?.project_id||'',scope:$('#memory-scope').value,source:'Informada pelo usuário'}});closeModal();await loadMemories();render();toast('Memória salva.');break;}case 'delete-memory':if(confirm('Esquecer esta memória? Ela deixará de ser usada em novas respostas.')){await api('/memories/'+encodeURIComponent(el.dataset.id),{method:'DELETE'});await loadMemories();render();toast('Memória esquecida.');}break;case 'export-memories':downloadJSON('memorias-estudio-local.json',{company_id:state.company,memories:state.memory});break;case 'backup':await backup();break;case 'open-path':await api('/open',{method:'POST',body:{path:el.dataset.path}});break;case 'open-data':await api('/open',{method:'POST',body:{path:state.data.data_dir||state.data.settings.data_dir}});break;case 'shutdown':if(confirm('Encerrar o Estúdio Local e seus serviços?')){await api('/shutdown',{method:'POST',body:{}});document.body.innerHTML='<div class="boot"><span class="brand-symbol">e</span><h1>Estúdio encerrado.</h1><p>Você pode fechar esta aba. Para voltar, use o atalho do aplicativo.</p></div>';}break;case 'repair':if(confirm('Verificar e reparar os componentes instalados? Seus projetos e cadastros serão preservados.')){await api('/setup',{method:'POST',body:{repair:true,remotion_license_ack:true,modules:['core']}});state.setupStep=3;state.data.installed=false;renderSetup();await pollSetup();}break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();const lock=['save-company','create-project','start-install','save-memory','save-transcript','upload-company','project-upload','draft-upload','draft-audio','download-company-bundle','confirm-company-import'].includes(el.dataset.action);if(lock)el.disabled=true;Promise.resolve(action(el)).catch(err=>toast(err.message,true)).finally(()=>{if(lock&&el.isConnected)el.disabled=false;});});
document.addEventListener('input',e=>{const field=e.target.dataset.colorField;if(field){const row=e.target.closest('[data-color-index]'),i=+row.dataset.colorIndex,c=state.companyDraft.colors[i];if(field==='picker'){c.hex=e.target.value.toUpperCase();row.querySelector('[data-color-field=hex]').value=c.hex;rgb(c.hex).forEach((v,j)=>row.querySelector(`[data-color-field="rgb-${j}"]`).value=v);}else if(field==='name'||field==='role')c[field]=e.target.value;else if(field==='hex'){const h=hex(e.target.value.startsWith('#')?e.target.value:'#'+e.target.value);e.target.setCustomValidity(h?'':'Use seis dígitos: #6147CD');if(h){c.hex=h;row.querySelector('[data-color-field=picker]').value=h;rgb(h).forEach((v,j)=>row.querySelector(`[data-color-field="rgb-${j}"]`).value=v);}}else if(field.startsWith('rgb-')){const values=[0,1,2].map(j=>Number(row.querySelector(`[data-color-field="rgb-${j}"]`).value));if(values.every(v=>Number.isInteger(v)&&v>=0&&v<=255)){c.hex='#'+values.map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase();row.querySelector('[data-color-field=hex]').value=c.hex;row.querySelector('[data-color-field=picker]').value=c.hex;}}updateBrandPreview();}if(e.target.name==='company-name'){state.companyDraft.name=e.target.value;updateBrandPreview();}});
document.addEventListener('change',e=>{if(e.target.id==='bundle-assets'){const media=$('#bundle-media');if(media){media.disabled=!e.target.checked;if(!e.target.checked)media.checked=false;}}if(e.target.id==='company-switch')selectCompany(e.target.value).catch(err=>toast(err.message,true));if(e.target.name==='project-audio'){captureProject();$('#audio-fields').innerHTML=audioFieldsHTML(state.projectDraft);}if(e.target.id==='memory-toggle'){const enabled=e.target.checked;api('/settings',{method:'PUT',body:{memory_enabled:enabled}}).then(()=>{state.data.settings.memory_enabled=enabled;toast(enabled?'Memória automática ativada.':'Memória automática desativada.');}).catch(err=>{e.target.checked=!enabled;toast(err.message,true);});}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const v=$('#chat-input').value.trim();if(v)sendChat(v).catch(err=>toast(err.message,true));}if(e.target.id==='search-form'){e.preventDefault();const q=new FormData(e.target).get('q');api('/search?company_id='+encodeURIComponent(state.company)+'&q='+encodeURIComponent(q)).then(r=>{state.results=Array.isArray(r)?r:r.results||[];render();}).catch(err=>toast(err.message,true));}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button][data-action]')){e.preventDefault();e.target.click();return;}if(e.key==='Escape'&&state.modal)closeModal();if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();const text=e.target.value.trim();if(text)sendChat(text).catch(err=>toast(err.message,true));}if(e.key==='Tab'&&$('#modal-root .modal')){const focusables=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]', $('#modal-root'));if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop-kind]');if(zone){e.preventDefault();zone.classList.add('dragging');}});
document.addEventListener('dragleave',e=>{e.target.closest('[data-drop-kind]')?.classList.remove('dragging');});
document.addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-kind]');if(zone){e.preventDefault();zone.classList.remove('dragging');uploadCompany(zone.dataset.dropKind,[...e.dataTransfer.files]).catch(err=>toast(err.message,true));}});
async function init(){try{await refresh();if(!state.data.installed){state.diagnostics=await api('/diagnostics').catch(()=>({}));state.setupStatus=await api('/setup/status').catch(()=>null);if(state.setupStatus&&['running','downloading','installing'].includes(state.setupStatus.status))state.setupStep=3;}render();state.poll=setInterval(async()=>{try{if(!state.data.installed&&state.setupStep===3)await pollSetup();else if(state.view==='chat'&&state.project&&!state.chatBusy)await loadJobs();else await api('/ping').catch(()=>{});}catch{/* Keep last truthful state; user can retry explicitly. */}},3000);}catch(err){$('#app').innerHTML=`<div class="boot"><span class="brand-symbol">e</span><h1>Tentando conectar ao estúdio...</h1><p>${esc(err.message)}</p><button class="btn primary" id="reload-app">Tentar novamente</button><p class="small">Certifique-se de que o terminal do Estúdio Local está aberto.</p></div>`;$('#reload-app').onclick=()=>location.reload();setTimeout(()=>{if(!state.data?.companies?.length)init();},3000);}}
init();
